#include <stdio.h>
#include <string.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 1;
    for (int i = 0; i < n; i++) {
        char lenh[16];
        if (scanf("%15s", lenh) != 1) return 1;
        if (strcmp(lenh, "HALT") == 0) break;
        if (strcmp(lenh, "IO") == 0) {
            char c[16];
            if (scanf("%15s", c) != 1) return 1;
            printf("%c", c[0]);
        }
    }
    printf("\n");
    return 0;
}
